function calcular(lineas, descuentoPct, tipoIva) {
  const subtotal = lineas.reduce((s, l) => s + l.importe, 0);
  const pct = aCentimos(descuentoPct);
  const descuento = Math.round(subtotal * pct / 10000);
  const base = subtotal - descuento;
  const iva = Math.round(base * tipoIva / 100);
  return { subtotal, descuento, base, iva, total: base + iva };
}
